import type {} from '@memoized-dom/compiler/jsx';
export function App({ value }: { value: string | undefined }) {
  return <section>if (value !== undefined) {
    <button onClick={async () => { await Promise.resolve(); console.log(value.toUpperCase()); }}>
      value.toUpperCase()
    </button>
